        "category": "2",
        "raw": "만성 수생 환경유해성 물질 구분 2",
        "line": "p1:L25"
      }
    ],
    "signal_word": "위험",
    "pictograms": [
      {
        "code": "GHS02"
      },
      {
        "code": "GHS07"
      },
      {
        "code": "GHS08"
      },
